def apply_merge(tokens, pair):
    out, i = [], 0
    while i < len(tokens):
        if i+1 < len(tokens) and (tokens[i], tokens[i+1]) == pair:
            out.append(tokens[i] + tokens[i+1])
            i += 2
        else:
            out.append(tokens[i])
            i += 1
    return out

assert apply_merge(list("banana"), ("a", "n")) == ["b", "an", "an", "a"]
